def load_defaults(apps, schema_editor):
    from intel.config import schema

    Config = apps.get_model("intel", "RankingConfig")
    Change = apps.get_model("intel", "RankingConfigChange")
    from django.utils import timezone

    now = timezone.now()
    for surface, version, name in LOAD:
        if Config.objects.filter(surface=surface, version=version).exists():
            continue
        with (DEFAULTS / f"{name}.json").open(encoding="utf-8") as fh:
            params = json.load(fh)
        schema.check(surface, params)
        active = version == 1
        Config.objects.create(
            surface=surface,
            version=version,
            status="active" if active else "draft",
            params=params,
            schema_version=params["schema_version"],
            note=f"package defaults ({name}.json)",
            activated_at=now if active else None,
        )
        Change.objects.create(
            surface=surface,
            from_version=None,
            to_version=version,
            action="created",
            reason="loaded by migration intel/0004",
        )
        if active:
            Change.objects.create(
                surface=surface,
                from_version=None,
                to_version=version,
                action="activated",
                reason="loaded by migration intel/0004",
            )


